{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Participation in a prior anti-IL-33 class medication clinical study",
      "quote": "Participation in a prior anti-IL-33 class medication clinical study"
    },
    {
      "kind": "exclusion",
      "text": "Body mass index <16 kg/m2",
      "quote": "Body mass index <16 kg/m2",
      "thresholds": [
        {
          "test": "BMI",
          "op": "<",
          "value": 16,
          "unit": "kg/m2"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Treatment with an investigational drug within 8 weeks or within 5 half-lives (if known), whichever is longer, before the baseline visit",
      "quote": "Treatment with an investigational drug within 8 weeks or within 5 half-lives (if known), whichever is longer, before the baseline visit"
    },
    {
      "kind": "exclusion",
      "text": "Use of immunosuppressive/immunomodulating drugs (e.g., systemic corticosteroids, cyclosporine, mycophenolate-mofetil, IFN-γ, Janus kinase inhibitors, azathioprine, methotrexate) within 4 weeks before baseline or any condition likely to require such treatment during first 4 weeks of study treatment",
      "quote": "Immunosuppressive/immunomodulating drugs (eg, systemic corticosteroids, cyclosporine, mycophenolate-mofetil, IFN-γ, Janus kinase inhibitors, azathioprine, methotrexate, etc)"
    },
    {
      "kind": "exclusion",
      "text": "Phototherapy for AD within 4 weeks before baseline or any condition likely to require such treatment during first 4 weeks of study treatment",
      "quote": "Phototherapy for AD"
    },
    {
      "kind": "exclusion",
      "text": "Treatment with TCS, TCI, or topical crisaborole within 1 week before the baseline visit",
      "quote": "Treatment with TCS, TCI, or topical crisaborole within 1 week before the baseline visit"
    },
    {
      "kind": "exclusion",
      "text": "Treatment with any cell-depleting agents including but not limited to rituximab within 6 months before baseline or until lymphocyte count returns to normal, whichever is longer",
      "quote": "Any cell-depleting agents including but not limited to rituximab: within 6 months before the baseline visit, or until lymphocyte count returns to normal, whichever is longer"
    },
    {
      "kind": "exclusion",
      "text": "Treatment with other biologics (including dupilumab) within 5 half-lives (if known) or 16 weeks prior to baseline visit, whichever is longer",
      "quote": "Other biologics (including dupilumab): within 5 half-lives (if known) or 16 weeks prior to baseline visit, whichever is longer"
    },
    {
      "kind": "exclusion",
      "text": "Initiation of treatment of AD with prescription moisturizers or moisturizers containing additives such as ceramide, hyaluronic acid, urea, or filaggrin degradation products during the screening period (patients may continue using stable doses if initiated before screening)",
      "quote": "Initiation of treatment of AD with prescription moisturizers or moisturizers containing additives such as ceramide, hyaluronic acid, urea, or filaggrin degradation products during the screening period"
    },
    {
      "kind": "exclusion",
      "text": "Regular use (more than 2 visits per week) of a tanning booth/parlor within 4 weeks of the baseline visit",
      "quote": "Regular use (more than 2 visits per week) of a tanning booth/parlor within 4 weeks of the baseline visit"
    },
    {
      "kind": "exclusion",
      "text": "Planned or anticipated use of any prohibited medications and procedures during study treatment",
      "quote": "Planned or anticipated use of any prohibited medications and procedures during study treatment"
    },
    {
      "kind": "exclusion",
      "text": "Treatment with a live (attenuated) vaccine within 12 weeks before the baseline visit",
      "quote": "Treatment with a live (attenuated) vaccine within 12 weeks before the baseline visit"
    },
    {
      "kind": "exclusion",
      "text": "Active chronic or acute infection requiring treatment with systemic antibiotics, antivirals, antiparasitics, antiprotozoals, or antifungals within 2 weeks before baseline, or superficial skin infections within 1 week before baseline",
      "quote": "Active chronic or acute infection requiring treatment with systemic antibiotics, antivirals, antiparasitics, antiprotozoals, or antifungals within 2 weeks before the baseline visit, or superficial skin infections within 1 week before the baseline visit"
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected history of immunosuppression, including history of invasive opportunistic infections (e.g., tuberculosis, histoplasmosis, listeriosis, coccidioidomycosis, pneumocystosis, aspergillosis) despite infection resolution, or unusually frequent, recurrent, or prolonged infections per investigator judgment",
      "quote": "Known or suspected history of immunosuppression, including history of invasive opportunistic infections (eg, tuberculosis [TB]*, histoplasmosis, listeriosis, coccidioidomycosis, pneumocystosis, aspergillosis) despite infection resolution"
    },
    {
      "kind": "exclusion",
      "text": "Positive TB QuantiFERON test result at screening",
      "quote": "Patients with a positive TB QuantiFERON test result at screening will be excluded from the study.",
      "thresholds": [
        {
          "test": "QuantiFERON",
          "op": "positive",
          "value": 0
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "History of human immunodeficiency virus (HIV) infection or positive HIV serology at screening",
      "quote": "History of human immunodeficiency virus (HIV) infection or positive HIV serology at screening"
    },
    {
      "kind": "exclusion",
      "text": "Positive with hepatitis B surface antigen (HBsAg), hepatitis B core antibody (HBcAb), or hepatitis C virus antibody (HCV Ab) at the screening visit",
      "quote": "Positive with hepatitis B surface antigen (HBsAg), hepatitis B core antibody (HBcAb), or hepatitis C virus antibody (HCV Ab) at the screening visit"
    },
    {
      "kind": "exclusion",
      "text": "At baseline, presence of any conditions listed as criteria for study drug discontinuation",
      "quote": "At baseline, presence of any conditions listed as criteria for study drug discontinuation"
    },
    {
      "kind": "exclusion",
      "text": "Presence of skin comorbidities that may interfere with study assessments",
      "quote": "Presence of skin comorbidities that may interfere with study assessments"
    },
    {
      "kind": "exclusion",
      "text": "History of cancer, with exceptions for adequately treated basal cell carcinoma or carcinoma in situ of the cervix, or other malignancies successfully treated for >10 years prior to screening with no evidence of recurrence",
      "quote": "History of cancer, with the exceptions of: Patients with adequately treated basal cell carcinoma or carcinoma in situ of the cervix"
    },
    {
      "kind": "exclusion",
      "text": "Diagnosed active endoparasitic infections; suspected or high risk of endoparasitic infection, unless clinical and (if necessary) laboratory assessment have ruled out active infection before randomization",
      "quote": "Diagnosed active endoparasitic infections; suspected or high risk of endoparasitic infection, unless clinical and (if necessary) laboratory assessment have ruled out active infection before randomization"
    },
    {
      "kind": "exclusion",
      "text": "History of alcohol or drug abuse within 2 years of the screening visit",
      "quote": "History of alcohol or drug abuse within 2 years of the screening visit"
    },
    {
      "kind": "exclusion",
      "text": "Severe concomitant illness(es) that would adversely affect participation, including short life expectancy, uncontrolled diabetes (HbA1c ≥9%), uncontrolled cerebrocardiovascular conditions, severe renal conditions, hepatobiliary conditions (Child-Pugh class B or C), neurological conditions, active major autoimmune diseases, other severe endocrinological, gastrointestinal, metabolic, pulmonary, or lymphatic diseases",
      "quote": "Severe concomitant illness(es) that, in the investigator’s judgment, would adversely affect the patient’s participation in the study.",
      "thresholds": [
        {
          "test": "HbA1c",
          "op": ">=",
          "value": 9,
          "unit": "%"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Any other medical or psychological condition (including relevant laboratory abnormalities at screening) that may suggest a new and/or insufficiently understood disease, present unreasonable risk, make participation unreliable, or interfere with study assessments",
      "quote": "Any other medical or psychological condition (including relevant laboratory abnormalities at screening) that, in the opinion of the investigator, may suggest a new and/or insufficiently understood disease"
    },
    {
      "kind": "exclusion",
      "text": "Planned or anticipated major surgical procedure during the patient’s participation in this study",
      "quote": "Planned or anticipated major surgical procedure during the patient’s participation in this study"
    },
    {
      "kind": "exclusion",
      "text": "Patient is a member of the investigational team or his/her immediate family",
      "quote": "Patient is a member of the investigational team or his/her immediate family"
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding women, or women planning to become pregnant or breastfeed during the study",
      "quote": "Pregnant or breastfeeding women, or women planning to become pregnant or breastfeed during the study"
    },
    {
      "kind": "exclusion",
      "text": "Women of childbearing potential (WOCBP) who are unwilling to practice highly effective contraception prior to initial dose, during study, and for at least 20 weeks after last dose",
      "quote": "Women of childbearing potential (WOCBP)* who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 20 weeks after the last dose of study drug."
    },
    {
      "kind": "exclusion",
      "text": "Known sensitivity to doxycycline and/or tetracycline or to any of the components of the investigational product formulation",
      "quote": "Known sensitivity to doxycycline and/or tetracycline or to any of the components of the investigational product formulation."
    },
    {
      "kind": "exclusion",
      "text": "Patients who are committed to an institution by virtue of an order issued either by the judicial or the administrative authorities",
      "quote": "Patients who are committed to an institution by virtue of an order issued either by the judicial or the administrative authorities will be excluded from this study"
    }
  ]
}
